def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "execute_order_b": And([
            self.delegate_revoked,
            self.helper_cached_session,
            self.helper_old_token,
            self.legacy_endpoint_active
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
